function lfLog(key, vars) {
  var tab = LF_LOG.en;
  var s = tab[key];
  if (typeof s !== 'string') s = LF_LOG.en[key] || key;
  s = String(s);
  if (vars && typeof vars === 'object') {
    for (var k in vars) {
      if (!Object.prototype.hasOwnProperty.call(vars, k)) continue;
      s = s.split('{' + k + '}').join(String(vars[k]));
    }
  }
  return s;
}
